/// The list every bundled profile comes from: calls `$cb!` with one line
/// per profile, `Type: geometry, prior, (trained), (accurate), typical
/// bytes, bytes at the top;`. [`BUNDLED`] and [`decode()`](crate::decode)
/// are built from it, and the crate's tests use it to cover each profile.
#[doc(hidden)]
#[macro_export]
macro_rules! __bundled {
    ($cb:ident) => {
        $cb! {
            East30K12: East30, Slow, (-4, 32), (-60, 70), 103, 151;
            East30K12Mixed: East30, Mixed, (-20, 70), (-60, 70), 108, 130;
            East30K12Fast: East30, Fast, (-20, 70), (-60, 70), 114, 118;
            East30K16: East30, Slow, (-4, 32), (-60, 120), 108, 224;
            East30K16Mixed: East30, Mixed, (-20, 120), (-60, 120), 118, 162;
            East30K16Fast: East30, Fast, (-20, 120), (-60, 120), 131, 133;
            East30K20: East30, Slow, (-4, 32), (-60, 165), 115, 258;
            East30K20Mixed: East30, Mixed, (-20, 165), (-60, 165), 126, 167;
            East30K20Fast: East30, Fast, (-20, 165), (-60, 165), 146, 146;
            East30K24: East30, Slow, (-4, 32), (-60, 200), 119, 264;
            East30K24Mixed: East30, Mixed, (-20, 200), (-60, 200), 134, 197;
            East30K24Fast: East30, Fast, (-20, 200), (-60, 200), 156, 157;
            East30Offset: East30Offset, Slow, (-4, 32), (-60, 70), 114, 143;
            East30OffsetK12Mixed: East30Offset, Mixed, (-20, 70), (-60, 70), 116, 136;
            East30OffsetK12Fast: East30Offset, Fast, (-20, 70), (-60, 70), 124, 124;
            East30OffsetK16: East30Offset, Slow, (-4, 32), (-60, 110), 119, 210;
            East30OffsetK16Mixed: East30Offset, Mixed, (-20, 110), (-60, 110), 126, 150;
            East30OffsetK16Fast: East30Offset, Fast, (-20, 110), (-60, 110), 140, 136;
            East30OffsetK20: East30Offset, Slow, (-4, 32), (-60, 150), 124, 260;
            East30OffsetK20Mixed: East30Offset, Mixed, (-20, 150), (-60, 150), 135, 157;
            East30OffsetK20Fast: East30Offset, Fast, (-20, 150), (-60, 150), 153, 147;
            East30OffsetK24: East30Offset, Slow, (-4, 32), (-60, 200), 128, 312;
            East30OffsetK24Mixed: East30Offset, Mixed, (-20, 200), (-60, 200), 142, 180;
            East30OffsetK24Fast: East30Offset, Fast, (-20, 200), (-60, 200), 168, 158;
        }
    };
}

/// Thermistor positions a preset's tables were trained for.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[non_exhaustive]
pub enum Geometry {
    /// The classic East30 probe: needles 6 mm downstream and 6 mm upstream
    /// of the heater.
    East30,
    /// The offset East30 probe: 10 mm downstream (above), 5 mm upstream.
    East30Offset,
}

impl Geometry {
    /// Downstream and upstream thermistor distances along the flow, cm
    /// (upstream negative).
    #[must_use]
    pub const fn positions_cm(self) -> [f64; 2] {
        match self {
            Self::East30 => [0.6, -0.6],
            Self::East30Offset => [1.0, -0.5],
        }
    }
}

/// The heat-pulse velocities a preset's tables were trained on. The prior
/// only changes record size, never what decodes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[non_exhaustive]
pub enum Prior {
    /// Uniform over −4..32 cm/h: smallest records at typical flows.
    Slow,
    /// 85 % of the curves at N(5, 6) cm/h, 15 % uniform over the preset's
    /// range: close to the slow size at typical flows, much smaller at
    /// high flow.
    Mixed,
    /// Uniform over the preset's range: about the same size at every flow.
    Fast,
}

/// One bundled profile in the [`BUNDLED`] catalog.
///
/// Sizes and ranges are measured on simulated 6-thermistor records (one
/// probe: three thermistors at each [`Geometry::positions_cm`],
/// k = 0.0025 cm²/s, 1 s pulse, 350 counts at the no-flow 6 mm peak, raw
/// noise 1.53 counts RMS). Accurate means a full-curve RMS error of at most
/// 0.5 counts and no sample more than 5 counts off the noise-free curve.
#[derive(Debug, Clone, Copy, PartialEq)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
#[cfg_attr(feature = "serde", derive(serde::Serialize))]
#[non_exhaustive]
pub struct PresetInfo {
    /// The Rust type, e.g. `"East30K20Mixed"`.
    pub type_name: &'static str,
    /// [`Profile::NAME`].
    pub name: &'static str,
    /// [`Profile::ID`], the id in the extended header.
    pub id: u32,
    /// [`Profile::COMPACT_VERSION`], the version byte of 12-channel records.
    pub compact_version: Option<u8>,
    /// Thermistor positions the tables were trained for.
    pub geometry: Geometry,
    /// [`Profile::KNOTS`].
    pub knots: u8,
    /// The log-time offset `t0`, seconds.
    pub t0_s: f64,
    /// The training velocity prior.
    pub prior: Prior,
    /// The range of the training prior, cm/h.
    pub trained_cm_h: (i16, i16),
    /// The flows reproduced accurately, cm/h.
    pub accurate_cm_h: (i16, i16),
    /// Mean bytes of a 6-thermistor record at 0–20 cm/h.
    pub typical_bytes: u16,
    /// Bytes of a 6-thermistor record at the top of the accurate range.
    pub bytes_at_top: u16,
}

impl PresetInfo {
    #[allow(clippy::too_many_arguments)]
    const fn of<P: Profile>(
        type_name: &'static str,
        geometry: Geometry,
        prior: Prior,
        trained_cm_h: (i16, i16),
        accurate_cm_h: (i16, i16),
        typical_bytes: u16,
        bytes_at_top: u16,
    ) -> Self {
        Self {
            type_name,
            name: P::NAME,
            id: P::ID,
            compact_version: P::COMPACT_VERSION,
            geometry,
            knots: P::KNOTS,
            t0_s: P::T0_FRAMES as f64 * P::FRAME_PERIOD_US as f64 / 1e6,
            prior,
            trained_cm_h,
            accurate_cm_h,
            typical_bytes,
            bytes_at_top,
        }
    }

    /// The bundled preset with profile id `id`.
    ///
    /// ```
    /// use sfk1::{East30K20Mixed, PresetInfo, Profile};
    /// let p = PresetInfo::by_id(East30K20Mixed::ID).unwrap();
    /// assert_eq!((p.type_name, p.knots, p.accurate_cm_h), ("East30K20Mixed", 20, (-60, 165)));
    /// ```
    #[must_use]
    pub const fn by_id(id: u32) -> Option<&'static PresetInfo> {
        let mut i = 0;
        while i < BUNDLED.len() {
            if BUNDLED[i].id == id {
                return Some(&BUNDLED[i]);
            }
            i += 1;
        }
        None
    }

    /// The bundled preset whose 12-channel records have version byte `v`
    /// (`0x53` is [`East30K12`](crate::East30K12), `0x54`
    /// [`East30K16`](crate::East30K16)).
    #[must_use]
    pub const fn by_compact_version(v: u8) -> Option<&'static PresetInfo> {
        let mut i = 0;
        while i < BUNDLED.len() {
            if let Some(c) = BUNDLED[i].compact_version {
                if c == v {
                    return Some(&BUNDLED[i]);
                }
            }
            i += 1;
        }
        None
    }
}

macro_rules! catalog {
    ($($ty:ident: $geom:ident, $prior:ident, ($tlo:literal, $thi:literal), ($lo:literal, $hi:literal), $typ:literal, $top:literal;)*) => {
        /// Every bundled profile, for servers and tools to list or look up
        /// ([`PresetInfo::by_id`]). [`decode()`](crate::decode) decodes
        /// records of each.
        ///
        /// ```
        /// let fast: Vec<_> = sfk1::BUNDLED.iter().filter(|p| p.accurate_cm_h.1 >= 150).map(|p| p.type_name).collect();
        /// assert!(fast.contains(&"East30K20"));
        /// ```
        pub const BUNDLED: &[PresetInfo] = &[$(
            PresetInfo::of::<crate::$ty>(stringify!($ty), Geometry::$geom, Prior::$prior, ($tlo, $thi), ($lo, $hi), $typ, $top)
        ),*];

        /// Decode `record` with the bundled profile its header names, if any.
        #[cfg(feature = "alloc")]
        pub(crate) fn decode_bundled(
            record: &[u8],
            layout: crate::Layout,
        ) -> Option<Result<crate::Decoded, crate::DecodeError>> {
            $(
                if crate::decode::profile_matches::<crate::$ty>(layout) {
                    return Some(crate::Decoder::<crate::$ty>::new(record).map(|d| d.to_decoded()));
                }
            )*
            None
        }
    };
}

crate::__bundled!(catalog);
